"use client";

import React, { useMemo, useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import * as THREE from "three";

interface MatrixGridProps {
  theme: "dark" | "paper";
}

function HardwareMatrix({ theme }: MatrixGridProps) {
  const groupRef = useRef<THREE.Group>(null);
  const meshRefs = useRef<(THREE.Mesh | null)[]>([]);

  const cells = useMemo(() => {
    const items: { x: number; z: number; isAccent: boolean; phase: number }[] = [];
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col < 5; col++) {
        const x = (col - 2) * 0.62;
        const z = (row - 2) * 0.62;
        const isAccent = row === 1 && col === 3;
        items.push({
          x,
          z,
          isAccent,
          phase: row * 0.55 + col * 0.45,
        });
      }
    }
    return items;
  }, []);

  useFrame((state) => {
    const t = state.clock.getElapsedTime();
    const px = state.pointer.x;
    const py = state.pointer.y;

    if (groupRef.current) {
      groupRef.current.rotation.y = THREE.MathUtils.lerp(
        groupRef.current.rotation.y,
        -0.58 + px * 0.2,
        0.06
      );
      groupRef.current.rotation.x = THREE.MathUtils.lerp(
        groupRef.current.rotation.x,
        0.55 - py * 0.14,
        0.06
      );
    }

    meshRefs.current.forEach((mesh, idx) => {
      if (!mesh) return;
      const cell = cells[idx];
      const dx = cell.x * 0.35 - px;
      const dz = cell.z * 0.35 + py;
      const dist = Math.sqrt(dx * dx + dz * dz);
      const wave = Math.sin(t * 1.8 - cell.phase) * 0.045;
      const press = Math.max(0, 1 - dist * 1.1) * 0.14;
      mesh.position.y = wave - press;
    });
  });

  const baseColor = theme === "paper" ? "#D8D3C8" : "#22242A";
  const accentColor = "#FF4D00";

  return (
    <group ref={groupRef} rotation={[0.55, -0.58, 0]}>
      {/* Matte chassis plate */}
      <mesh position={[0, -0.22, 0]}>
        <boxGeometry args={[3.4, 0.18, 3.4]} />
        <meshStandardMaterial
          color={theme === "paper" ? "#C5BFB2" : "#111215"}
          roughness={0.85}
          metalness={0.15}
        />
      </mesh>

      {cells.map((cell, i) => (
        <mesh
          key={i}
          ref={(el) => {
            meshRefs.current[i] = el;
          }}
          position={[cell.x, 0, cell.z]}
        >
          <boxGeometry args={[0.5, 0.24, 0.5]} />
          <meshStandardMaterial
            color={cell.isAccent ? accentColor : baseColor}
            roughness={cell.isAccent ? 0.38 : 0.65}
            metalness={0.12}
          />
        </mesh>
      ))}
    </group>
  );
}

export default function TactileCanvas({ theme }: MatrixGridProps) {
  return (
    <div className="h-full w-full select-none">
      <Canvas
        camera={{ position: [0, 1.4, 4.7], fov: 36 }}
        dpr={[1, 2]}
        gl={{ antialias: true, alpha: true }}
      >
        <ambientLight intensity={theme === "paper" ? 1.15 : 0.75} />
        <directionalLight position={[4, 7, 5]} intensity={theme === "paper" ? 1.5 : 1.9} />
        <directionalLight position={[-4, 3, -3]} intensity={0.45} />
        <HardwareMatrix theme={theme} />
      </Canvas>
    </div>
  );
}
